'use strict';
let stageCategory='dungeon';
function updateCombatMeters(){const playing=player.map!=='town'&&!!run;$('combatMeter').hidden=!playing;$('eliteMeter').hidden=!playing||!!run?.trial||!!run?.tutorial;if(!playing)return;$('roundClock').textContent=run.tutorial?'ฝึกสอน':'ฟาร์ม';$('comboFill').style.width=(run.combo?Math.max(0,1-(run.time-run.lastKill)/5)*100:0)+'%';$('comboCount').textContent=run.combo;$('eliteFill').style.width=(run.eliteProgress||0)+'%';$('eliteCount').textContent=(run.eliteProgress||0)+' / 100'}
function selectStageCategory(category){stageCategory=category;for(const [id,key]of [['dungeonCategory','dungeon'],['bossCategory','boss']]){$(id).setAttribute('aria-selected',String(category===key));$(id).classList.toggle('selected',category===key)}$('stageList').hidden=category!=='dungeon';$('trialEntry').hidden=category!=='boss'}
window.addEventListener('DOMContentLoaded',()=>{$('dungeonCategory').onclick=()=>selectStageCategory('dungeon');$('bossCategory').onclick=()=>selectStageCategory('boss')});

let controlWindow=null;
const WINDOW_KEYS={Digit1:'skill',Numpad1:'skill',Digit2:'party',Numpad2:'party',Digit3:'enchant',Numpad3:'enchant'};
function openControlWindow(kind){if(screen!=='play'||run?.finished||(!$('modal').hidden&&!controlWindow))return;if(controlWindow===kind){closeModal();return}if(!$('characterOverlay').hidden)closeCharacterWindow();const titles={skill:'Skill',party:'Party',enchant:'Enchant'};if(!titles[kind])return;controlWindow=kind;const body=document.createElement('div');body.id='controlWindowBody';body.className='control-window-body';body.dataset.window=kind;body.setAttribute('aria-label',titles[kind]);modal(kind==='skill'?JOBS[player.job].name:titles[kind],body,kind==='skill'?[]:[['ปิด',closeModal,true]]);$('modal').classList.toggle('skill-modal',kind==='skill');if(kind==='skill'){selectedSwordSkill=null;renderSwordSkillWindow(body);$('closeSkillBtn').focus()}}
function handleWindowShortcut(e){if(screen!=='play'||run?.finished)return false;if(e.code==='Tab'&&controlWindow){e.preventDefault();if(!e.repeat){closeModal();openCharacterWindow()}return true}const kind=WINDOW_KEYS[e.code];if(!kind||(!$('modal').hidden&&!controlWindow))return false;e.preventDefault();if(!e.repeat)openControlWindow(kind);return true}
window.addEventListener('DOMContentLoaded',()=>{for(const [id,kind]of [['skillMenuBtn','skill'],['partyMenuBtn','party'],['enchantMenuBtn','enchant']])$(id).onclick=()=>openControlWindow(kind)});
